cat > /tmp/test_lsp15.py << 'EOF'
import subprocess
import json
import time
import select

proc = subprocess.Popen(['./executable', '--stdio'], 
                       stdin=subprocess.PIPE, 
                       stdout=subprocess.PIPE, 
                       stderr=subprocess.PIPE)

def send_msg(msg):
    content = json.dumps(msg).encode('utf-8')
    header = f"Content-Length: {len(content)}\r\n\r\n".encode('utf-8')
    proc.stdin.write(header + content)
    proc.stdin.flush()

def read_msg():
    headers = {}
    while True:
        line = proc.stdout.readline()
        if not line or line == b'\r\n':
            break
        if b':' in line:
            key, val = line.decode().strip().split(':', 1)
            headers[key.strip()] = val.strip()

    if 'Content-Length' in headers:
        content_len = int(headers['Content-Length'])
        content = proc.stdout.read(content_len)
        return json.loads(content.decode('utf-8'))
    return None

send_msg({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"capabilities":{},"rootUri":None,"processId":None}})
resp = read_msg()

send_msg({"jsonrpc":"2.0","method":"initialized","params":{}})

# Test: notification with id field set (request ID but it's a notification method)
# Actually let's check what missing jsonrpc notification means vs missing jsonrpc with id

# OK we know the server responds to missing jsonrpc regardless of whether id is present

# Let's test textDocument notifications that have special handling
for method, params in [
    ("textDocument/didOpen", {
        "textDocument":{
            "uri":"file:///tmp/test.rs",
            "languageId":"rust",
            "version":1,
            "text":"fn main() {}\n"
        }
    }),
    ("textDocument/didChange", {
        "textDocument":{"uri":"file:///tmp/test.rs","version":2},
        "contentChanges":[{"text":"fn main() {}\n"}]
    }),
    ("textDocument/didClose", {
        "textDocument":{"uri":"file:///tmp/test.rs"}
    }),
]:
    send_msg({"jsonrpc":"2.0","method":method,"params":params})
    time.sleep(0.1)
    r, _, _ = select.select([proc.stdout], [], [], 0.2)
    if r:
        resp = read_msg()
        print(f"{method}: {json.dumps(resp)}", flush=True)
    else:
        print(f"{method}: no response (notification handled OK)", flush=True)

# Test workspace/didChangeWorkspaceFolders
send_msg({"jsonrpc":"2.0","method":"workspace/didChangeWorkspaceFolders","params":{
    "event":{"added":[{"uri":"file:///tmp","name":"tmp"}],"removed":[]}
}})
time.sleep(0.1)
r, _, _ = select.select([proc.stdout], [], [], 0.2)
if r:
    resp = read_msg()
    print(f"workspace/didChangeWorkspaceFolders: {json.dumps(resp)}", flush=True)
else:
    print(f"workspace/didChangeWorkspaceFolders: no response (handled OK)", flush=True)

# shutdown
send_msg({"jsonrpc":"2.0","id":9,"method":"shutdown"})
resp = read_msg()
print(f"shutdown: {json.dumps(resp)}", flush=True)
send_msg({"jsonrpc":"2.0","method":"exit"})
proc.stdin.close()
proc.wait(timeout=5)
EOF
