        #[arg(value_name = "path")]
        path: Option<PathBuf>,

        /// Run the check for all targets instead of current only
        #[arg(long = "all-targets")]
        all_targets: bool,

        /// Run the check for all features instead of the current active ones only
        #[arg(long = "all-features")]
        all_features: bool,
    },

