#[derive(Subcommand, Debug)]
enum ToolchainCommands {
    /// Install the toolchain
    Install {
        /// Runtime directory path to install RustOwl toolchain
        #[arg(long = "path")]
        path: Option<PathBuf>,

        /// Install Rust toolchain only
        #[arg(long = "skip-rustowl-toolchain")]
        skip_rustowl_toolchain: bool,
    },

    /// Uninstall the toolchain
    Uninstall,
}

#[tokio::main]
async fn main() {
    // Initialize logging
    init_logger();

    let cli = Cli::parse();

    if cli.version {
        println!("RustOwl v1.0.0-rc.1");
        return;
    }

    match &cli.command {
        Some(Commands::Completions { shell }) => {
            let mut cmd = Cli::command();
            let name = cmd.get_name().to_string();
            generate(*shell, &mut cmd, name, &mut io::stdout());
            return;
        }
        Some(Commands::Clean) => {
            toolchain::clean().await;
            return;
        }
        Some(Commands::Toolchain { command }) => {
            match command {
                ToolchainCommands::Install { path, skip_rustowl_toolchain } => {
                    toolchain::install(path.clone(), *skip_rustowl_toolchain).await;
                }
                ToolchainCommands::Uninstall => {
                    toolchain::uninstall().await;
                }
            }
            return;
        }
        Some(Commands::Check { path, all_targets, all_features }) => {
            let target_path = path.clone().unwrap_or_else(|| {
                std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
            });
            let result = lsp::check(target_path, *all_targets, *all_features).await;
            if result.is_err() {
                log::error!(target: "rustowl", "Analyze failed");
                std::process::exit(1);
            }
            return;
        }
        None => {
            if cli.stdio {
                // Run as LSP server
                lsp::run_lsp_server().await;
            } else {
                // Print version info and hint
                eprintln!("RustOwl v1.0.0-rc.1");
                eprintln!("This is an LSP server. You can use --help flag to show help.");
            }
        }
    }
}

fn init_logger() {
    use log::LevelFilter;
    use std::io::Write;

    let env = env_logger::Env::default().default_filter_or("info");
    env_logger::Builder::from_env(env)
        .format(|buf, record| {
            let now = chrono::Utc::now();
            let timestamp = now.format("%Y-%m-%dT%H:%M:%S%.3fZ");
            writeln!(
                buf,
                "{} {:<5} [{}] {}",
                timestamp,
                record.level(),
                record.target(),
                record.args()
            )
        })
        .init();
}
