use std::path::{Path, PathBuf};

fn find_cargo_toml(path: &Path) -> Option<PathBuf> {
    let cargo_toml = path.join("Cargo.toml");
    if cargo_toml.exists() {
        return Some(cargo_toml);
    }

    // Check if the path itself is a .rs file inside a cargo project
    if path.extension().map(|e| e == "rs").unwrap_or(false) {
        let mut parent = path.parent();
        while let Some(p) = parent {
            let cargo_toml = p.join("Cargo.toml");
            if cargo_toml.exists() {
                return Some(cargo_toml);
            }
            parent = p.parent();
        }
    }

    None
}

pub async fn analyze_path(path: &Path, all_targets: bool, all_features: bool) -> Result<(), ()> {
    let abs_path = path.canonicalize().unwrap_or_else(|_| path.to_path_buf());

    // Check if it's a valid cargo project
    if find_cargo_toml(&abs_path).is_none() {
        log::warn!(target: "rustowl::lsp::analyze", "Invalid analysis target: {}", abs_path.display());
        return Err(());
    }

    Ok(())
}

