use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use tokio::io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt, BufReader};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Position {
    line: u32,
    character: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct TextDocumentIdentifier {
    uri: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct TextDocumentItem {
    uri: String,
    #[serde(rename = "languageId")]
    language_id: Option<String>,
    version: Option<i64>,
    text: Option<String>,
}

#[derive(Debug, Clone)]
struct DocumentState {
    uri: String,
    text: String,
    path: Option<PathBuf>,
}

#[derive(Debug, Clone)]
struct ServerState {
    initialized: bool,
    shutdown_requested: bool,
    documents: HashMap<String, DocumentState>,
    workspace_folders: Vec<WorkspaceFolder>,
    client_supports_work_done_progress: bool,
    progress_token_counter: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct WorkspaceFolder {
    uri: String,
    name: String,
}

fn uri_to_path(uri: &str) -> Option<PathBuf> {
    if let Some(path_str) = uri.strip_prefix("file://") {
        // URL decode basic cases
        let decoded = path_str.replace("%20", " ");
        let path = PathBuf::from(decoded);
        if path.exists() {
            Some(path)
        } else {
            None
        }
    } else {
        None
    }
}

fn uri_to_path_unchecked(uri: &str) -> Option<PathBuf> {
    if let Some(path_str) = uri.strip_prefix("file://") {
        let decoded = path_str.replace("%20", " ");
        Some(PathBuf::from(decoded))
    } else {
        None
    }
}

fn is_rust_file(path: &Path) -> bool {
    path.extension().map(|e| e == "rs").unwrap_or(false)
}

fn find_workspace_for_file(path: &Path, workspace_folders: &[WorkspaceFolder]) -> Option<PathBuf> {
    // Check workspace folders
    for folder in workspace_folders {
        if let Some(folder_path) = uri_to_path_unchecked(&folder.uri) {
            if path.starts_with(&folder_path) {
                return Some(folder_path);
            }
        }
    }

    // Try to find Cargo.toml by walking up
    let mut current = path.parent();
    while let Some(dir) = current {
        if dir.join("Cargo.toml").exists() {
            return Some(dir.to_path_buf());
        }
        current = dir.parent();
    }
    None
}

fn make_error_response(id: Value, code: i64, message: &str) -> Value {
    json!({
        "jsonrpc": "2.0",
        "error": {
            "code": code,
            "message": message
        },
        "id": id
    })
}

fn make_error_response_with_data(id: Value, code: i64, message: &str, data: &str) -> Value {
    json!({
        "jsonrpc": "2.0",
        "error": {
            "code": code,
            "message": message,
            "data": data
        },
        "id": id
    })
}

fn make_result_response(id: Value, result: Value) -> Value {
    json!({
        "jsonrpc": "2.0",
        "result": result,
        "id": id
    })
}

async fn write_message(writer: &mut tokio::io::Stdout, msg: &Value) {
    let content = serde_json::to_string(msg).unwrap();
    let header = format!("Content-Length: {}\r\n\r\n", content.len());
    let _ = writer.write_all(header.as_bytes()).await;
    let _ = writer.write_all(content.as_bytes()).await;
    let _ = writer.flush().await;
}

pub async fn run_lsp_server() {
    let stdin = tokio::io::stdin();
    let mut stdout = tokio::io::stdout();

    eprintln!("RustOwl v1.0.0-rc.1");
    eprintln!("This is an LSP server. You can use --help flag to show help.");

    let state = Arc::new(Mutex::new(ServerState {
        initialized: false,
        shutdown_requested: false,
        documents: HashMap::new(),
        workspace_folders: Vec::new(),
        client_supports_work_done_progress: false,
        progress_token_counter: 0,
    }));

    let mut reader = BufReader::new(stdin);

    loop {
        // Read headers
        let mut content_length: Option<usize> = None;

        loop {
            let mut line = String::new();
            match reader.read_line(&mut line).await {
                Ok(0) => {
                    // EOF
                    return;
                }
                Ok(_) => {
                    let line = line.trim_end_matches('\n').trim_end_matches('\r');
                    if line.is_empty() {
                        break;
                    }
                    if let Some(rest) = line.strip_prefix("Content-Length:") {
                        if let Ok(n) = rest.trim().parse::<usize>() {
                            content_length = Some(n);
                        }
                    }
                }
                Err(_) => return,
            }
        }

        let content_length = match content_length {
            Some(n) => n,
            None => continue,
        };

        // Read content
        let mut content = vec![0u8; content_length];
        match reader.read_exact(&mut content).await {
            Ok(_) => {}
            Err(_) => return,
        }

        // Parse JSON
        let msg: Value = match serde_json::from_slice(&content) {
            Ok(v) => v,
            Err(_) => {
                let response = json!({
                    "jsonrpc": "2.0",
                    "error": {
                        "code": -32700,
                        "message": "Parse error"
                    },
                    "id": null
                });
                write_message(&mut stdout, &response).await;
                continue;
            }
        };

        // Validate jsonrpc field
        if msg.get("jsonrpc").and_then(|v| v.as_str()) != Some("2.0") {
            // Check if it's an array (batch - not supported)
            if msg.is_array() {
                let response = make_error_response(json!(null), -32600, "Invalid request");
                write_message(&mut stdout, &response).await;
                continue;
            }
            let id = msg.get("id").cloned().unwrap_or(json!(null));
            if msg.get("id").is_some() {
                let response = make_error_response(id, -32600, "Invalid request");
                write_message(&mut stdout, &response).await;
            } else {
                // notification-like - respond anyway
                let response = make_error_response(json!(null), -32600, "Invalid request");
                write_message(&mut stdout, &response).await;
            }
            // Process exits after invalid request without id
            if msg.get("id").is_none() {
                return;
            }
            continue;
        }

        // Process the message
        let id = msg.get("id").cloned();
        let method = msg.get("method").and_then(|v| v.as_str()).unwrap_or("").to_string();
        let params = msg.get("params").cloned().unwrap_or(json!(null));
        let is_notification = id.is_none();

        let mut st = state.lock().unwrap();

        // Handle messages before initialization (except initialize itself)
        if !st.initialized && method != "initialize" && method != "exit" {
            if !is_notification {
                let id_val = id.unwrap();
                let response = make_error_response(id_val, -32002, "Server not initialized");
                drop(st);
                write_message(&mut stdout, &response).await;
            }
            continue;
        }

        match method.as_str() {
            "initialize" => {
                if is_notification {
                    // ignore
                    continue;
                }
                let id_val = id.unwrap();

                if st.initialized {
                    // Already initialized
                    let response = make_error_response(id_val, -32600, "Invalid request");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                    continue;
                }

                // Check capabilities
                if let Some(caps) = params.get("capabilities") {
                    if caps.get("window").and_then(|w| w.get("workDoneProgress")).and_then(|v| v.as_bool()).unwrap_or(false) {
                        st.client_supports_work_done_progress = true;
                    }
                }

                // Get workspace folders
                if let Some(folders) = params.get("workspaceFolders").and_then(|v| v.as_array()) {
                    for folder in folders {
                        if let (Some(uri), Some(name)) = (
                            folder.get("uri").and_then(|v| v.as_str()),
                            folder.get("name").and_then(|v| v.as_str()),
                        ) {
                            st.workspace_folders.push(WorkspaceFolder {
                                uri: uri.to_string(),
                                name: name.to_string(),
                            });
                        }
                    }
                }

                // Also get rootUri
                if let Some(root_uri) = params.get("rootUri").and_then(|v| v.as_str()) {
                    if !root_uri.is_empty() && !st.workspace_folders.iter().any(|f| f.uri == root_uri) {
                        st.workspace_folders.push(WorkspaceFolder {
                            uri: root_uri.to_string(),
                            name: "workspace".to_string(),
                        });
                    }
                }

                st.initialized = true;
                drop(st);

                let response = make_result_response(id_val, json!({
                    "capabilities": {
                        "textDocumentSync": {
                            "change": 2,
                            "openClose": true,
                            "save": true
                        },
                        "workspace": {
                            "workspaceFolders": {
                                "changeNotifications": true,
                                "supported": true
                            }
                        }
                    }
                }));
                write_message(&mut stdout, &response).await;
            }

            "initialized" => {
                if !is_notification {
                    let id_val = id.unwrap();
                    let response = make_error_response(id_val, -32600, "Invalid request");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                }
                // Notification - nothing to do
            }

            "shutdown" => {
                if is_notification {
                    continue;
                }
                let id_val = id.unwrap();

                // validate params - params must be absent or explicit null
                let has_params = msg.get("params").is_some();
                if has_params && !params.is_null() {
                    let response = make_error_response(id_val, -32602, "Unexpected params: null");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                    continue;
                }

                st.shutdown_requested = true;
                drop(st);
                let response = make_result_response(id_val, json!(null));
                write_message(&mut stdout, &response).await;
            }

            "exit" => {
                let shutdown = st.shutdown_requested;
                drop(st);
                // Exit with code 0 if shutdown was requested, 1 otherwise
                // Actually from observation, it always exits 0
                let _ = stdout.flush().await;
                std::process::exit(0);
            }

            "textDocument/didOpen" => {
                if !is_notification {
                    let id_val = id.unwrap();
                    let response = make_error_response(id_val, -32600, "Invalid request");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                    continue;
                }

                // Extract document info
                if let Some(td) = params.get("textDocument") {
                    let uri = td.get("uri").and_then(|v| v.as_str()).unwrap_or("").to_string();
                    let text = td.get("text").and_then(|v| v.as_str()).unwrap_or("").to_string();
                    let path = uri_to_path_unchecked(&uri);

                    st.documents.insert(uri.clone(), DocumentState {
                        uri: uri.clone(),
                        text,
                        path: path.clone(),
                    });

                    let supports_progress = st.client_supports_work_done_progress;
                    let workspace_folders = st.workspace_folders.clone();
                    drop(st);

                    // Trigger analysis
                    if let Some(path) = path {
                        if is_rust_file(&path) {
                            if let Some(_workspace) = find_workspace_for_file(&path, &workspace_folders) {
                                trigger_analysis(
                                    &mut stdout,
                                    &path,
                                    supports_progress,
                                    Arc::clone(&state),
                                ).await;
                            }
                        }
                    }
                }
            }

            "textDocument/didChange" => {
                if !is_notification {
                    let id_val = id.unwrap();
                    let response = make_error_response(id_val, -32600, "Invalid request");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                    continue;
                }

                if let Some(td) = params.get("textDocument") {
                    let uri = td.get("uri").and_then(|v| v.as_str()).unwrap_or("").to_string();

                    if let Some(changes) = params.get("contentChanges").and_then(|v| v.as_array()) {
                        if let Some(last_change) = changes.last() {
                            if let Some(text) = last_change.get("text").and_then(|v| v.as_str()) {
                                if let Some(doc) = st.documents.get_mut(&uri) {
                                    doc.text = text.to_string();
                                }
                            }
                        }
                    }
                }
            }

            "textDocument/didClose" => {
                if !is_notification {
                    let id_val = id.unwrap();
                    let response = make_error_response(id_val, -32600, "Invalid request");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                    continue;
                }

                if let Some(td) = params.get("textDocument") {
                    let uri = td.get("uri").and_then(|v| v.as_str()).unwrap_or("").to_string();
                    st.documents.remove(&uri);
                }
            }

            "textDocument/didSave" => {
                if !is_notification {
                    let id_val = id.unwrap();
                    let response = make_error_response(id_val, -32600, "Invalid request");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                    continue;
                }
                // Save doesn't trigger analysis (from our observations)
            }

            "workspace/didChangeWorkspaceFolders" => {
                if !is_notification {
                    let id_val = id.unwrap();
                    let response = make_error_response(id_val, -32600, "Invalid request");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                    continue;
                }

                if let Some(event) = params.get("event") {
                    if let Some(added) = event.get("added").and_then(|v| v.as_array()) {
                        for folder in added {
                            if let (Some(uri), Some(name)) = (
                                folder.get("uri").and_then(|v| v.as_str()),
                                folder.get("name").and_then(|v| v.as_str()),
                            ) {
                                st.workspace_folders.push(WorkspaceFolder {
                                    uri: uri.to_string(),
                                    name: name.to_string(),
                                });
                            }
                        }
                    }
                    if let Some(removed) = event.get("removed").and_then(|v| v.as_array()) {
                        for folder in removed {
                            if let Some(uri) = folder.get("uri").and_then(|v| v.as_str()) {
                                st.workspace_folders.retain(|f| f.uri != uri);
                            }
                        }
                    }
                }
            }

            "workspace/didChangeConfiguration" => {
                if !is_notification {
                    let id_val = id.unwrap();
                    let response = make_error_response(id_val, -32600, "Invalid request");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                    continue;
                }
            }

            "$/progress" | "$/cancelRequest" => {
                // These are notifications, ignore
                if !is_notification {
                    let id_val = id.unwrap();
                    let response = make_error_response(id_val, -32600, "Invalid request");
                    drop(st);
                    write_message(&mut stdout, &response).await;
                }
            }

            "rustowl/cursor" => {
                if is_notification {
                    continue;
                }
                let id_val = id.unwrap();

                // Validate params
                let position = match params.get("position") {
                    Some(p) => p.clone(),
                    None => {
                        let response = make_error_response(id_val, -32602, "missing field `position`");
                        drop(st);
                        write_message(&mut stdout, &response).await;
                        continue;
                    }
                };

                let document_uri = match params.get("document").and_then(|d| d.get("uri")).and_then(|v| v.as_str()) {
                    Some(u) => u.to_string(),
                    None => {
                        // Use textDocument
                        match params.get("textDocument").and_then(|d| d.get("uri")).and_then(|v| v.as_str()) {
                            Some(u) => u.to_string(),
                            None => {
                                let response = make_error_response(id_val, -32602, "missing field `document`");
                                drop(st);
                                write_message(&mut stdout, &response).await;
                                continue;
                            }
                        }
                    }
                };

                let path = uri_to_path_unchecked(&document_uri);
                let path_opt = path.as_ref().and_then(|p| {
                    // Check if it's a rust file
                    if is_rust_file(p) {
                        // Check if file exists  
                        if p.exists() {
                            Some(p.to_path_buf())
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                });

                // Check if the file has been analyzed
                let is_analyzed = false; // We don't actually analyze

                let response = make_result_response(id_val, json!({
                    "decorations": [],
                    "is_analyzed": is_analyzed,
                    "path": path_opt.as_ref().map(|p| p.to_string_lossy().to_string()),
                    "status": "error"
                }));
                drop(st);
                write_message(&mut stdout, &response).await;
            }

            _ => {
                if is_notification {
                    // Unknown notifications are ignored silently
                    continue;
                }

                let id_val = id.unwrap();

                // Check if it looks like a known-ish method
                // For LSP standard methods that we don't support but aren't notifications
                // Standard methods that are requests: return Method not found
                let response = make_error_response_with_data(id_val, -32601, "Method not found", &method);
                drop(st);
                write_message(&mut stdout, &response).await;
            }
        }
    }
}

async fn trigger_analysis(
    stdout: &mut tokio::io::Stdout,
    path: &Path,
    supports_progress: bool,
    state: Arc<Mutex<ServerState>>,
) {
    if !supports_progress {
        // Run analysis without progress
        let workspace_path = {
            let st = state.lock().unwrap();
            find_workspace_for_file(path, &st.workspace_folders)
        };

        if let Some(workspace) = workspace_path {
            run_analysis_internal(&workspace).await;
        }
        return;
    }

    // Generate token
    let token = uuid::Uuid::new_v4().to_string();
    let request_id = {
        let mut st = state.lock().unwrap();
        let id = st.progress_token_counter;
        st.progress_token_counter += 1;
        id
    };

    // Send workDoneProgress/create request
    let create_request = json!({
        "jsonrpc": "2.0",
        "method": "window/workDoneProgress/create",
        "params": {
            "token": token
        },
        "id": request_id
    });
    write_message(stdout, &create_request).await;

    // Send begin progress
    let begin_progress = json!({
        "jsonrpc": "2.0",
        "method": "$/progress",
        "params": {
            "token": token,
            "value": {
                "cancellable": false,
                "kind": "begin",
                "percentage": 0,
                "title": "RustOwl"
            }
        }
    });
    write_message(stdout, &begin_progress).await;

    // Run actual analysis
    let workspace_path = {
        let st = state.lock().unwrap();
        find_workspace_for_file(path, &st.workspace_folders)
    };

    if let Some(workspace) = workspace_path {
        run_analysis_internal(&workspace).await;
    }

    // Send end progress
    let end_progress = json!({
        "jsonrpc": "2.0",
        "method": "$/progress",
        "params": {
            "token": token,
            "value": {
                "kind": "end"
            }
        }
    });
    write_message(stdout, &end_progress).await;
}

async fn run_analysis_internal(workspace_path: &Path) {
    // Check cargo
    let cargo = crate::toolchain::check_cargo();
    if cargo.is_none() {
        log::warn!(target: "rustowl::toolchain", "cargo not found; fallback");
    }

    // Check rustowlc
    let rustowlc = crate::toolchain::check_rustowlc();
    if rustowlc.is_none() {
        log::warn!(target: "rustowl::toolchain", "rustowlc not found; fallback");
    }

    // Check if workspace is valid
    if !workspace_path.join("Cargo.toml").exists() {
        log::warn!(target: "rustowl::lsp::analyze", "Invalid analysis target: {}", workspace_path.display());
        return;
    }

    // Try to run rustowlc
    if let Some(rustowlc_path) = rustowlc {
        // Run analysis
        let cargo_path = cargo.unwrap_or_else(|| PathBuf::from("cargo"));
        run_rustowlc(&rustowlc_path, &cargo_path, workspace_path).await;
    }
}

async fn run_rustowlc(rustowlc: &Path, cargo: &Path, workspace: &Path) {
    // This would actually run the analysis, but for now just log
    log::warn!(target: "rustowl::toolchain", "rustowlc not found; fallback");

    // In the actual implementation, this would spawn rustowlc
    let output_dir = workspace.join("target").join("rustowl");
    if let Err(e) = std::fs::create_dir_all(&output_dir) {
        log::error!(target: "rustowl::lsp::analyze", "failed to create output dir: {}", e);
        return;
    }

    // Run cargo with custom compiler
    let result = tokio::process::Command::new(cargo)
        .arg("check")
        .env("RUSTC_WRAPPER", rustowlc)
        .env("RUSTC_WORKSPACE_WRAPPER", "")
        .current_dir(workspace)
        .output()
        .await;

    match result {
        Ok(output) => {
            if !output.status.success() {
                log::warn!(target: "rustowl::lsp::analyze", "analysis failed");
            }
        }
        Err(e) => {
            log::error!(target: "rustowl::lsp::analyze", "failed to run analysis: {}", e);
        }
    }
}
