        }
    }
}

async fn trigger_analysis(
    stdout: &mut tokio::io::Stdout,
    path: &Path,
    supports_progress: bool,
    state: Arc<Mutex<ServerState>>,
) {
    if !supports_progress {
        // Run analysis without progress
        let workspace_path = {
            let st = state.lock().unwrap();
            find_workspace_for_file(path, &st.workspace_folders)
        };

        if let Some(workspace) = workspace_path {
            run_analysis_internal(&workspace).await;
        }
        return;
    }

    // Generate token
    let token = uuid::Uuid::new_v4().to_string();
    let request_id = {
        let mut st = state.lock().unwrap();
        let id = st.progress_token_counter;
        st.progress_token_counter += 1;
        id
    };

    // Send workDoneProgress/create request
    let create_request = json!({
        "jsonrpc": "2.0",
        "method": "window/workDoneProgress/create",
        "params": {
            "token": token
        },
        "id": request_id
    });
    write_message(stdout, &create_request).await;

    // Send begin progress
    let begin_progress = json!({
        "jsonrpc": "2.0",
        "method": "$/progress",
        "params": {
            "token": token,
            "value": {
                "cancellable": false,
                "kind": "begin",
                "percentage": 0,
                "title": "RustOwl"
            }
        }
    });
    write_message(stdout, &begin_progress).await;

    // Run actual analysis
    let workspace_path = {
        let st = state.lock().unwrap();
        find_workspace_for_file(path, &st.workspace_folders)
    };

    if let Some(workspace) = workspace_path {
        run_analysis_internal(&workspace).await;
    }

    // Send end progress
    let end_progress = json!({
        "jsonrpc": "2.0",
        "method": "$/progress",
        "params": {
            "token": token,
            "value": {
                "kind": "end"
            }
        }
    });
    write_message(stdout, &end_progress).await;
}

async fn run_analysis_internal(workspace_path: &Path) {
    // Check cargo
    let cargo = crate::toolchain::check_cargo();
    if cargo.is_none() {
        log::warn!(target: "rustowl::toolchain", "cargo not found; fallback");
    }

    // Check rustowlc
    let rustowlc = crate::toolchain::check_rustowlc();
    if rustowlc.is_none() {
