func isValidAnalysisTarget(path string) bool {
	// Check if the path contains a Cargo.toml (directly or by walking up)
	info, err := os.Stat(path)
	if err != nil {
		return false
	}

	if info.IsDir() {
		_, err := os.Stat(filepath.Join(path, "Cargo.toml"))
		return err == nil
	}

	// It's a file
	if filepath.Ext(path) == ".rs" {
		dir := filepath.Dir(path)
		for dir != "/" && dir != "." {
			_, err := os.Stat(filepath.Join(dir, "Cargo.toml"))
			if err == nil {
				return true
			}
			dir = filepath.Dir(dir)
		}
	}

	return false
}

