	defer l.mu.Unlock()
	now := time.Now().UTC()
	ts := now.Format("2006-01-02T15:04:05.000Z")
	fmt.Fprintf(os.Stderr, "%s %-5s [%s] %s\n", ts, level, target, msg)
}

func (l *RustOwlLogger) Info(target, msg string) { l.log("INFO", target, msg) }
func (l *RustOwlLogger) Warn(target, msg string) { l.log("WARN", target, msg) }
func (l *RustOwlLogger) Error(target, msg string) { l.log("ERROR", target, msg) }

func init() {
	logger = &RustOwlLogger{}
	log.SetOutput(io.Discard) // Suppress default logger
}

func main() {
	args := os.Args[1:]

	// Check for --version or -V first
	for _, arg := range args {
		if arg == "--version" || arg == "-V" {
			fmt.Printf("RustOwl v%s\n", Version)
			return
		}
	}

	// Check for --help or -h
	for _, arg := range args {
		if arg == "--help" || arg == "-h" {
			printMainHelp()
			return
		}
	}

	// Parse global flags
	var quietCount int
	var stdio bool
	remaining := []string{}

	i := 0
	for i < len(args) {
		switch args[i] {
		case "-q", "--quiet":
			quietCount++
		case "--stdio":
			stdio = true
		default:
			if !strings.HasPrefix(args[i], "-") {
				remaining = append(remaining, args[i:]...)
				i = len(args)
				continue
			}
			// Unknown flag before subcommand - treat as error
			fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n", args[i])
			fmt.Fprintf(os.Stderr, "Usage: rustowl [OPTIONS] [COMMAND]\n\n")
			fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
			os.Exit(2)
		}
		i++
	}
	_ = quietCount

	if len(remaining) == 0 {
		if stdio {
			runLSPServer()
		} else {
			fmt.Fprintf(os.Stderr, "RustOwl v%s\n", Version)
			fmt.Fprintf(os.Stderr, "This is an LSP server. You can use --help flag to show help.\n")
		}
		return
	}

	// Subcommand
	switch remaining[0] {
	case "check":
		runCheck(remaining[1:])
	case "clean":
		runClean(remaining[1:])
	case "toolchain":
		runToolchain(remaining[1:])
	case "completions":
		runCompletions(remaining[1:])
	case "help":
		if len(remaining) > 1 {
			runHelp(remaining[1:])
		} else {
			printMainHelp()
		}
	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\n", remaining[0])
		fmt.Fprintf(os.Stderr, "Usage: rustowl [OPTIONS] [COMMAND]\n\n")
		fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
		os.Exit(2)
	}
}

func printMainHelp() {
	fmt.Print(`Usage: rustowl [OPTIONS] [COMMAND]

Commands:
  check        Check availability
  clean        Remove artifacts from the target directory
  toolchain    Install or uninstall the toolchain
  completions  Generate shell completions
  help         Print this message or the help of the given subcommand(s)

Options:
  -V, --version   Print version
  -q, --quiet...  Suppress output
      --stdio     Use stdio to communicate with the LSP server
  -h, --help      Print help
`)
}

func runHelp(args []string) {
	if len(args) == 0 {
		printMainHelp()
