	}
	switch args[0] {
	case "check":
		printCheckHelp()
	case "clean":
		printCleanHelp()
	case "toolchain":
		if len(args) > 1 {
			switch args[1] {
			case "install":
				printToolchainInstallHelp()
			case "uninstall":
				printToolchainUninstallHelp()
			default:
				printToolchainHelp()
			}
		} else {
			printToolchainHelp()
		}
	case "completions":
