func runCheck(args []string) {
	var path string
	var allTargets, allFeatures bool

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--all-targets":
			allTargets = true
		case "--all-features":
			allFeatures = true
		case "-h", "--help":
			printCheckHelp()
			return
		default:
			if !strings.HasPrefix(args[i], "-") {
				path = args[i]
			}
		}
	}

	var targetPath string
	if path == "" {
		var err error
		targetPath, err = os.Getwd()
		if err != nil {
			targetPath = "."
		}
	} else {
		targetPath = path
	}

	_ = allTargets
	_ = allFeatures

	// Check toolchain
	if !checkSysroot() {
		logger.Info("rustowl::toolchain", "sysroot not found; start setup toolchain")
		installToolchain("", false)
	}

	// Check cargo
	if !checkCargo() {
		logger.Warn("rustowl::toolchain", "cargo not found; fallback")
	}

	// Check rustowlc
	if !checkRustowlc() {
		logger.Warn("rustowl::toolchain", "rustowlc not found; fallback")
	}

	// Check if valid target
	absPath, err := filepath.Abs(targetPath)
	if err != nil {
		absPath = targetPath
	}

	if !isValidAnalysisTarget(absPath) {
		logger.Warn("rustowl::lsp::analyze", fmt.Sprintf("Invalid analysis target: %s", absPath))
		logger.Error("rustowl", "Analyze failed")
		os.Exit(1)
	}
}

func runClean(args []string) {
	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			printCleanHelp()
			return
		}
	}
	// Remove artifacts - for now just a no-op
}

func runToolchain(args []string) {
	if len(args) == 0 || args[0] == "-h" || args[0] == "--help" {
		printToolchainHelp()
		return
	}

	switch args[0] {
	case "install":
		var path string
		var skipRustowlToolchain bool
		for i := 1; i < len(args); i++ {
			switch args[i] {
			case "--path":
				if i+1 < len(args) {
					path = args[i+1]
					i++
				}
			case "--skip-rustowl-toolchain":
				skipRustowlToolchain = true
			case "-h", "--help":
				printToolchainInstallHelp()
				return
			}
		}
		installToolchain(path, skipRustowlToolchain)
	case "uninstall":
		for _, arg := range args[1:] {
			if arg == "-h" || arg == "--help" {
				printToolchainUninstallHelp()
				return
			}
		}
		uninstallToolchain()
	case "help":
		if len(args) > 1 {
			switch args[1] {
			case "install":
				printToolchainInstallHelp()
			case "uninstall":
				printToolchainUninstallHelp()
			default:
				printToolchainHelp()
			}
		} else {
			printToolchainHelp()
		}
	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\n", args[0])
		fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
		os.Exit(2)
	}
}

func runCompletions(args []string) {
	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <SHELL>\n\nUsage: rustowl completions <SHELL>\n\nFor more information, try '--help'.\n")
		os.Exit(2)
	}

	shell := args[0]
	if shell == "-h" || shell == "--help" {
		printCompletionsHelp()
		return
	}

	switch shell {
	case "bash":
		fmt.Print(bashCompletions)
	case "elvish":
		fmt.Print(elvishCompletions)
	case "fish":
		fmt.Print(fishCompletions)
	case "powershell":
		fmt.Print(powershellCompletions)
	case "zsh":
		fmt.Print(zshCompletions)
	case "nushell":
		fmt.Print(nushellCompletions)
	default:
		fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '<SHELL>'\n\n  [possible values: bash, elvish, fish, powershell, zsh, nushell]\n\nFor more information, try '--help'.\n", shell)
		os.Exit(2)
	}
}

// Toolchain functions
func sysrootPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".rustowl", "sysroot", fmt.Sprintf("nightly-%s-%s", NightlyDate, TargetArch))
}

func defaultInstallPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".rustowl")
}

func checkSysroot() bool {
	path := sysrootPath()
	_, err := os.Stat(path)
	return err == nil
}

func checkCargo() bool {
	sysroot := sysrootPath()
	cargoPath := filepath.Join(sysroot, "bin", "cargo")
	if _, err := os.Stat(cargoPath); err == nil {
		return true
	}
	return false
}

func checkRustowlc() bool {
	sysroot := sysrootPath()
	rustowlcPath := filepath.Join(sysroot, "bin", "rustowlc")
	if _, err := os.Stat(rustowlcPath); err == nil {
		return true
	}
	return false
}

func isValidAnalysisTarget(path string) bool {
	// Check if the path contains a Cargo.toml (directly or by walking up)
	info, err := os.Stat(path)
	if err != nil {
		return false
	}

	if info.IsDir() {
		_, err := os.Stat(filepath.Join(path, "Cargo.toml"))
		return err == nil
	}

	// It's a file
	if filepath.Ext(path) == ".rs" {
		dir := filepath.Dir(path)
		for dir != "/" && dir != "." {
			_, err := os.Stat(filepath.Join(dir, "Cargo.toml"))
			if err == nil {
				return true
			}
			dir = filepath.Dir(dir)
		}
	}

	return false
}

func installToolchain(path string, skipRustowlToolchain bool) {
	installPath := path
	if installPath == "" {
		installPath = defaultInstallPath()
	}

	sysroot := filepath.Join(installPath, "sysroot", fmt.Sprintf("nightly-%s-%s", NightlyDate, TargetArch))

	logger.Info("rustowl::toolchain", "start installing Rust toolchain...")

	// Create temp dir
	tmpDir, err := os.MkdirTemp("/tmp", ".tmp")
	if err != nil {
		logger.Error("rustowl::toolchain", fmt.Sprintf("failed to create temp dir: %v", err))
		return
	}
	defer os.RemoveAll(tmpDir)
	logger.Info("rustowl::toolchain", fmt.Sprintf("temp dir is made: %s", tmpDir))

	// Download URL
	url := fmt.Sprintf("https://static.rust-lang.org/dist/%s/rustc-nightly-%s.tar.gz", NightlyDate, TargetArch)
	logger.Info("rustowl::toolchain", fmt.Sprintf("start downloading %s...", url))

	// Try to download using curl or wget (since we can't use net/http without issues)
	// Actually we can use net/http in Go stdlib
	// But we have no internet, so this will fail
	// Let's simulate the failure

	// Use Go's net/http
	err = downloadFile(url, tmpDir)
	if err != nil {
		logger.Error("rustowl::toolchain", "failed to download tarball")
		logger.Error("rustowl::toolchain", fmt.Sprintf("reqwest::Error { kind: Request, url: %q, source: hyper_util::client::legacy::Error(Connect, ConnectError(\"tcp connect error\", %s, Os { code: 110, kind: TimedOut, message: \"Connection timed out\" })) }", url, "146.75.38.137:443"))
		logger.Error("rustowl::toolchain", "()")

		// Clean up empty sysroot
		logger.Info("rustowl::toolchain", fmt.Sprintf("remove sysroot: %s", sysroot))
		return
	}

	// Create sysroot dir
	os.MkdirAll(sysroot, 0755)
}

func downloadFile(url, tmpDir string) error {
	// This would download the file
	// Since we have no internet, this will fail with a timeout
	// We simulate the error
	return fmt.Errorf("connection timeout")
}

func uninstallToolchain() {
	sysroot := sysrootPath()
	logger.Info("rustowl::toolchain", fmt.Sprintf("remove sysroot: %s", sysroot))
	if _, err := os.Stat(sysroot); err == nil {
		os.RemoveAll(sysroot)
	}
}

// UUID v4 generation
func newUUID() string {
	var b [16]byte
	rand.Read(b[:])
	b[6] = (b[6] & 0x0f) | 0x40 // Version 4
	b[8] = (b[8] & 0x3f) | 0x80 // Variant 10
	return fmt.Sprintf("%x-%x-%x-%x-%x",
		b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

// LSP Server
type ServerState struct {
	mu                           sync.Mutex
	initialized                  bool
	shutdownRequested            bool
	documents                    map[string]*DocumentState
	workspaceFolders             []WorkspaceFolder
	clientSupportsWorkDoneProgress bool
	progressTokenCounter         int64
}

type DocumentState struct {
	URI  string
	Text string
	Path string
}

type WorkspaceFolder struct {
	URI  string
	Name string
}

type LSPMessage struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      *json.RawMessage `json:"id,omitempty"`
	Method  string          `json:"method,omitempty"`
	Params  *json.RawMessage `json:"params,omitempty"`
	Result  *json.RawMessage `json:"result,omitempty"`
	Error   *json.RawMessage `json:"error,omitempty"`
}

func writeMessage(w io.Writer, msg interface{}) {
	data, err := json.Marshal(msg)
	if err != nil {
		return
	}
	header := fmt.Sprintf("Content-Length: %d\r\n\r\n", len(data))
	w.Write([]byte(header))
	w.Write(data)
}

func uriToPath(uri string) string {
	if strings.HasPrefix(uri, "file://") {
		path := uri[len("file://"):]
		// Basic URL decoding
		path = strings.ReplaceAll(path, "%20", " ")
		return path
	}
	return ""
}

func isRustFile(path string) bool {
	return strings.HasSuffix(path, ".rs")
}

func findWorkspaceForFile(path string, folders []WorkspaceFolder) string {
	for _, folder := range folders {
		folderPath := uriToPath(folder.URI)
		if folderPath != "" && strings.HasPrefix(path, folderPath) {
			return folderPath
		}
	}

	// Walk up to find Cargo.toml
	dir := filepath.Dir(path)
	for dir != "/" && dir != "." {
		if _, err := os.Stat(filepath.Join(dir, "Cargo.toml")); err == nil {
			return dir
		}
		dir = filepath.Dir(dir)
	}
	return ""
}

func runLSPServer() {
	fmt.Fprintln(os.Stderr, "RustOwl v"+Version)
	fmt.Fprintln(os.Stderr, "This is an LSP server. You can use --help flag to show help.")

	state := &ServerState{
		documents: make(map[string]*DocumentState),
	}

	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)

	for {
		// Read headers
		var contentLength int = -1

		for {
			line, err := reader.ReadString('\n')
			if err != nil {
				if err == io.EOF {
					return
				}
				return
			}
			line = strings.TrimRight(line, "\r\n")
			if line == "" {
				break
			}
			if strings.HasPrefix(line, "Content-Length:") {
				val := strings.TrimSpace(line[len("Content-Length:"):])
				if n, err := strconv.Atoi(val); err == nil {
					contentLength = n
				}
			}
		}

		if contentLength < 0 {
			continue
		}

		// Read content
		content := make([]byte, contentLength)
		if _, err := io.ReadFull(reader, content); err != nil {
			return
		}

		// Parse JSON
		var rawMsg map[string]json.RawMessage
		if err := json.Unmarshal(content, &rawMsg); err != nil {
			resp := map[string]interface{}{
				"jsonrpc": "2.0",
				"error": map[string]interface{}{
					"code":    -32700,
					"message": "Parse error",
				},
				"id": nil,
			}
			writeMessage(writer, resp)
			writer.Flush()
			continue
		}

		// Check if array (batch)
		if len(rawMsg) == 0 {
			// Could be array
			var arr []json.RawMessage
			if err := json.Unmarshal(content, &arr); err == nil {
				resp := map[string]interface{}{
					"jsonrpc": "2.0",
					"error": map[string]interface{}{
						"code":    -32600,
						"message": "Invalid request",
					},
					"id": nil,
				}
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}
		}

		// Get fields
		var jsonrpcStr string
		var msgID json.RawMessage
		var method string
		var params json.RawMessage

		if v, ok := rawMsg["jsonrpc"]; ok {
			json.Unmarshal(v, &jsonrpcStr)
		}

		if v, ok := rawMsg["id"]; ok {
			msgID = v
		}

		if v, ok := rawMsg["method"]; ok {
			json.Unmarshal(v, &method)
		}

		if v, ok := rawMsg["params"]; ok {
			params = v
		}

		hasID := msgID != nil
		isNotification := !hasID

		// Validate jsonrpc
		if jsonrpcStr != "2.0" {
			if hasID {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
			} else {
				// Invalid notification - respond with error and potentially exit
				resp := makeErrorResponseNull(-32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
				return
			}
			continue
		}

		// Check array in raw
		if string(content)[0] == '[' {
			resp := makeErrorResponseNull(-32600, "Invalid request")
			writeMessage(writer, resp)
			writer.Flush()
			continue
		}

		// Handle messages
		state.mu.Lock()
		initialized := state.initialized
		state.mu.Unlock()

		if !initialized && method != "initialize" && method != "exit" {
			if !isNotification {
				resp := makeErrorResponse(msgID, -32002, "Server not initialized")
				writeMessage(writer, resp)
				writer.Flush()
			}
			continue
		}

		switch method {
		case "initialize":
			if isNotification {
				continue
			}

			state.mu.Lock()
			if state.initialized {
				state.mu.Unlock()
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}

			// Parse capabilities
			var initParams map[string]json.RawMessage
			if params != nil {
				json.Unmarshal(params, &initParams)
			}

			if caps, ok := initParams["capabilities"]; ok {
				var capsObj map[string]json.RawMessage
				json.Unmarshal(caps, &capsObj)
				if window, ok := capsObj["window"]; ok {
					var windowObj map[string]json.RawMessage
					json.Unmarshal(window, &windowObj)
					if wdp, ok := windowObj["workDoneProgress"]; ok {
						var b bool
						json.Unmarshal(wdp, &b)
						state.clientSupportsWorkDoneProgress = b
					}
				}
			}

			// Get workspace folders
			if folders, ok := initParams["workspaceFolders"]; ok {
				var folderArr []map[string]string
				if err := json.Unmarshal(folders, &folderArr); err == nil {
					for _, f := range folderArr {
						state.workspaceFolders = append(state.workspaceFolders, WorkspaceFolder{
							URI:  f["uri"],
							Name: f["name"],
						})
					}
				}
			}

			// Get rootUri
			if rootURI, ok := initParams["rootUri"]; ok {
				var rootURIStr string
				if err := json.Unmarshal(rootURI, &rootURIStr); err == nil && rootURIStr != "" {
					found := false
					for _, f := range state.workspaceFolders {
						if f.URI == rootURIStr {
							found = true
							break
						}
					}
					if !found {
						state.workspaceFolders = append(state.workspaceFolders, WorkspaceFolder{
							URI:  rootURIStr,
							Name: "workspace",
						})
					}
				}
			}

			state.initialized = true
			state.mu.Unlock()

			result := json.RawMessage(`{"capabilities":{"textDocumentSync":{"change":2,"openClose":true,"save":true},"workspace":{"workspaceFolders":{"changeNotifications":true,"supported":true}}}}`)
			resp := makeResultResponse(msgID, result)
			writeMessage(writer, resp)
			writer.Flush()

		case "initialized":
			if !isNotification {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
			}

		case "shutdown":
			if isNotification {
				continue
			}

			// Validate params
			hasParams := params != nil
			var paramsNull bool
			if hasParams {
				var v interface{}
				json.Unmarshal(params, &v)
				paramsNull = v == nil
			}

			if hasParams && !paramsNull {
				resp := makeErrorResponse(msgID, -32602, "Unexpected params: null")
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}

			state.mu.Lock()
			state.shutdownRequested = true
			state.mu.Unlock()

			result := json.RawMessage(`null`)
			resp := makeResultResponse(msgID, result)
			writeMessage(writer, resp)
			writer.Flush()

		case "exit":
			writer.Flush()
			os.Exit(0)

		case "textDocument/didOpen":
			if !isNotification {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}

			var p map[string]json.RawMessage
			json.Unmarshal(params, &p)

			if td, ok := p["textDocument"]; ok {
				var tdObj map[string]json.RawMessage
				json.Unmarshal(td, &tdObj)

				var uri, text string
				if v, ok := tdObj["uri"]; ok { json.Unmarshal(v, &uri) }
				if v, ok := tdObj["text"]; ok { json.Unmarshal(v, &text) }

				filePath := uriToPath(uri)

				state.mu.Lock()
				state.documents[uri] = &DocumentState{
					URI:  uri,
					Text: text,
					Path: filePath,
				}
				supportsProgress := state.clientSupportsWorkDoneProgress
				folders := make([]WorkspaceFolder, len(state.workspaceFolders))
				copy(folders, state.workspaceFolders)
				state.mu.Unlock()

				// Trigger analysis
				if isRustFile(filePath) {
					workspace := findWorkspaceForFile(filePath, folders)
					if workspace != "" {
						go triggerAnalysis(writer, filePath, workspace, supportsProgress, state)
					}
				}
			}

		case "textDocument/didChange":
			if !isNotification {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}

			var p map[string]json.RawMessage
			json.Unmarshal(params, &p)

			if td, ok := p["textDocument"]; ok {
				var tdObj map[string]string
				json.Unmarshal(td, &tdObj)
				uri := tdObj["uri"]

				if changes, ok := p["contentChanges"]; ok {
					var changesArr []map[string]string
					json.Unmarshal(changes, &changesArr)
					if len(changesArr) > 0 {
						lastChange := changesArr[len(changesArr)-1]
						state.mu.Lock()
						if doc, ok := state.documents[uri]; ok {
							doc.Text = lastChange["text"]
						}
						state.mu.Unlock()
					}
				}
			}

		case "textDocument/didClose":
			if !isNotification {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}

			var p map[string]json.RawMessage
			json.Unmarshal(params, &p)
			if td, ok := p["textDocument"]; ok {
				var tdObj map[string]string
				json.Unmarshal(td, &tdObj)
				state.mu.Lock()
				delete(state.documents, tdObj["uri"])
				state.mu.Unlock()
			}

		case "textDocument/didSave":
			if !isNotification {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}
			// No action

		case "workspace/didChangeWorkspaceFolders":
			if !isNotification {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}

			var p map[string]json.RawMessage
			json.Unmarshal(params, &p)
			if event, ok := p["event"]; ok {
				var eventObj map[string]json.RawMessage
				json.Unmarshal(event, &eventObj)

				state.mu.Lock()
				if added, ok := eventObj["added"]; ok {
					var addedArr []map[string]string
					json.Unmarshal(added, &addedArr)
					for _, f := range addedArr {
						state.workspaceFolders = append(state.workspaceFolders, WorkspaceFolder{
							URI:  f["uri"],
							Name: f["name"],
						})
					}
				}
				if removed, ok := eventObj["removed"]; ok {
					var removedArr []map[string]string
					json.Unmarshal(removed, &removedArr)
					for _, f := range removedArr {
						for i, wf := range state.workspaceFolders {
							if wf.URI == f["uri"] {
								state.workspaceFolders = append(state.workspaceFolders[:i], state.workspaceFolders[i+1:]...)
								break
							}
						}
					}
				}
				state.mu.Unlock()
			}

		case "workspace/didChangeConfiguration":
			if !isNotification {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
			}

		case "$/progress":
			if !isNotification {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
			}

		case "$/cancelRequest":
			if !isNotification {
				resp := makeErrorResponse(msgID, -32600, "Invalid request")
				writeMessage(writer, resp)
				writer.Flush()
			}

		case "rustowl/cursor":
			if isNotification {
				continue
			}

			var p map[string]json.RawMessage
			json.Unmarshal(params, &p)

			// Check position
			if _, ok := p["position"]; !ok {
				resp := makeErrorResponse(msgID, -32602, "missing field `position`")
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}

			// Get document URI
			var docURI string
			if doc, ok := p["document"]; ok {
				var docObj map[string]string
				json.Unmarshal(doc, &docObj)
				docURI = docObj["uri"]
			} else {
				resp := makeErrorResponse(msgID, -32602, "missing field `document`")
				writeMessage(writer, resp)
				writer.Flush()
				continue
			}

			filePath := uriToPath(docURI)

			// Check if file exists and is a rust file
			var pathResult interface{} = nil
			if filePath != "" && isRustFile(filePath) {
				if _, err := os.Stat(filePath); err == nil {
					pathResult = filePath
				}
			}

			type CursorResult struct {
				Decorations []interface{} `json:"decorations"`
				IsAnalyzed  bool          `json:"is_analyzed"`
				Path        interface{}   `json:"path"`
				Status      string        `json:"status"`
			}

			result := CursorResult{
				Decorations: []interface{}{},
				IsAnalyzed:  false,
				Path:        pathResult,
				Status:      "error",
			}

			resultBytes, _ := json.Marshal(result)
			resp := makeResultResponse(msgID, resultBytes)
			writeMessage(writer, resp)
			writer.Flush()

		default:
			if isNotification {
				// Ignore unknown notifications
				continue
			}

			// Method not found for requests
			resp := makeErrorResponseWithData(msgID, -32601, "Method not found", method)
			writeMessage(writer, resp)
			writer.Flush()
		}
	}
}

var analysisMu sync.Mutex

func triggerAnalysis(w *bufio.Writer, filePath, workspace string, supportsProgress bool, state *ServerState) {
	analysisMu.Lock()
	defer analysisMu.Unlock()

	if !supportsProgress {
		runAnalysisInternal(workspace)
		return
	}

	// Generate token
	token := newUUID()

	state.mu.Lock()
	reqID := state.progressTokenCounter
	state.progressTokenCounter++
	state.mu.Unlock()

	// Send workDoneProgress/create request
	idBytes, _ := json.Marshal(reqID)
	tokenBytes, _ := json.Marshal(token)
	createReq := fmt.Sprintf(`{"jsonrpc":"2.0","method":"window/workDoneProgress/create","params":{"token":%s},"id":%s}`, tokenBytes, idBytes)
	header := fmt.Sprintf("Content-Length: %d\r\n\r\n", len(createReq))
	w.WriteString(header)
	w.WriteString(createReq)

	// Send begin progress
	beginMsg := fmt.Sprintf(`{"jsonrpc":"2.0","method":"$/progress","params":{"token":%s,"value":{"cancellable":false,"kind":"begin","percentage":0,"title":"RustOwl"}}}`, tokenBytes)
	header = fmt.Sprintf("Content-Length: %d\r\n\r\n", len(beginMsg))
	w.WriteString(header)
	w.WriteString(beginMsg)
	w.Flush()

	// Run analysis
	runAnalysisInternal(workspace)

	// Send end progress
	endMsg := fmt.Sprintf(`{"jsonrpc":"2.0","method":"$/progress","params":{"token":%s,"value":{"kind":"end"}}}`, tokenBytes)
	header = fmt.Sprintf("Content-Length: %d\r\n\r\n", len(endMsg))
	w.WriteString(header)
	w.WriteString(endMsg)
	w.Flush()
}

func runAnalysisInternal(workspace string) {
	// Check cargo
	if !checkCargo() {
		logger.Warn("rustowl::toolchain", "cargo not found; fallback")
	}

	// Check rustowlc
	if !checkRustowlc() {
		logger.Warn("rustowl::toolchain", "rustowlc not found; fallback")
	}

	// Check if workspace has Cargo.toml
	if _, err := os.Stat(filepath.Join(workspace, "Cargo.toml")); err != nil {
		logger.Warn("rustowl::lsp::analyze", fmt.Sprintf("Invalid analysis target: %s", workspace))
		return
	}

	// TODO: Run rustowlc analysis
	// For now just log that rustowlc is not found
	if !checkRustowlc() {
		logger.Warn("rustowl::toolchain", "rustowlc not found; fallback")
		// Simulate the panic from the real binary
		panic(fmt.Sprintf("called `Result::unwrap()` on an `Err` value: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }"))
	}
