func sysrootPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".rustowl", "sysroot", fmt.Sprintf("nightly-%s-%s", NightlyDate, TargetArch))
}

func defaultInstallPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".rustowl")
}

func checkSysroot() bool {
	path := sysrootPath()
	_, err := os.Stat(path)
	return err == nil
}

func checkCargo() bool {
	sysroot := sysrootPath()
	cargoPath := filepath.Join(sysroot, "bin", "cargo")
	if _, err := os.Stat(cargoPath); err == nil {
		return true
	}
	return false
}

func checkRustowlc() bool {
	sysroot := sysrootPath()
	rustowlcPath := filepath.Join(sysroot, "bin", "rustowlc")
	if _, err := os.Stat(rustowlcPath); err == nil {
		return true
	}
	return false
}

func isValidAnalysisTarget(path string) bool {
	// Check if the path contains a Cargo.toml (directly or by walking up)
	info, err := os.Stat(path)
	if err != nil {
		return false
	}

	if info.IsDir() {
		_, err := os.Stat(filepath.Join(path, "Cargo.toml"))
		return err == nil
	}

	// It's a file
	if filepath.Ext(path) == ".rs" {
		dir := filepath.Dir(path)
		for dir != "/" && dir != "." {
