func main() {
	args := os.Args[1:]

	// Check for --version or -V first (before subcommand)
	for _, arg := range args {
		if arg == "--version" || arg == "-V" {
			fmt.Printf("RustOwl v%s\n", Version)
			return
		}
	}

	// Check for --help or -h
	for _, arg := range args {
		if arg == "--help" || arg == "-h" {
			printMainHelp()
			return
		}
	}

	// Parse global flags
	var stdio bool
	remaining := []string{}

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "-q", "--quiet":
			// suppress output (counted but not used)
		case "--stdio":
			stdio = true
		default:
			if strings.HasPrefix(args[i], "-") {
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: rustowl [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", args[i])
				os.Exit(2)
			}
			remaining = append(remaining, args[i:]...)
			i = len(args)
		}
	}

	if len(remaining) == 0 {
		if stdio {
			runLSPServer()
		} else {
			fmt.Fprintf(os.Stderr, "RustOwl v%s\n", Version)
			fmt.Fprintf(os.Stderr, "This is an LSP server. You can use --help flag to show help.\n")
		}
		return
	}

	switch remaining[0] {
	case "check":
		runCheck(remaining[1:])
	case "clean":
		runClean(remaining[1:])
	case "toolchain":
		runToolchain(remaining[1:])
	case "completions":
		runCompletions(remaining[1:])
	case "help":
		runHelp(remaining[1:])
	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\nUsage: rustowl [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", remaining[0])
		os.Exit(2)
	}
}

