func sysrootPath() string {
	home, err := os.UserHomeDir()
	if err != nil {
		home = "/tmp"
	}
	return filepath.Join(home, ".rustowl", "sysroot",
		fmt.Sprintf("nightly-%s-%s", NightlyDate, TargetArch))
}

func defaultInstallBase() string {
	home, err := os.UserHomeDir()
	if err != nil {
		home = "/tmp"
	}
	return filepath.Join(home, ".rustowl")
}

func checkSysroot() bool {
	_, err := os.Stat(sysrootPath())
	return err == nil
}

func checkCargo() bool {
	_, err := os.Stat(filepath.Join(sysrootPath(), "bin", "cargo"))
	return err == nil
}

func checkRustowlc() bool {
	_, err := os.Stat(filepath.Join(sysrootPath(), "bin", "rustowlc"))
	return err == nil
}

func installToolchain(installBase string, skipRustowlToolchain bool) {
	if installBase == "" {
		installBase = defaultInstallBase()
	}

	sysroot := filepath.Join(installBase, "sysroot",
		fmt.Sprintf("nightly-%s-%s", NightlyDate, TargetArch))

	logInfo("rustowl::toolchain", "start installing Rust toolchain...")

	// Create temp dir
	tmpDir, err := os.MkdirTemp("/tmp", ".tmp")
	if err != nil {
		logError("rustowl::toolchain", fmt.Sprintf("failed to create temp dir: %v", err))
		return
	}
	logInfo("rustowl::toolchain", fmt.Sprintf("temp dir is made: %s", tmpDir))

	// Create sysroot dir
	os.MkdirAll(sysroot, 0755)

	// Download URL
	url := fmt.Sprintf("https://static.rust-lang.org/dist/%s/rustc-nightly-%s.tar.gz",
		NightlyDate, TargetArch)
	logInfo("rustowl::toolchain", fmt.Sprintf("start downloading %s...", url))

	// Simulate download failure (no internet)
	// In real implementation, this would use net/http
	// For now, simulate timeout
	time.Sleep(30 * time.Second) // Simulate ~30s timeout

	logError("rustowl::toolchain", "failed to download tarball")

	// The exact reqwest error format - we approximate with a similar error
	logError("rustowl::toolchain", fmt.Sprintf(
		`reqwest::Error { kind: Request, url: %q, source: hyper_util::client::legacy::Error(Connect, ConnectError("tcp connect error", 146.75.38.137:443, Os { code: 110, kind: TimedOut, message: "Connection timed out" })) }`,
		url))
	logError("rustowl::toolchain", "()")
}

func uninstallToolchain() {
	sysroot := sysrootPath()
	logInfo("rustowl::toolchain", fmt.Sprintf("remove sysroot: %s", sysroot))
	if _, err := os.Stat(sysroot); err == nil {
		os.RemoveAll(sysroot)
	}
}

