func runCheck(args []string) {
	var pathArg string
	var allTargets, allFeatures bool

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--all-targets":
			allTargets = true
		case "--all-features":
			allFeatures = true
		case "-h", "--help":
