			if !strings.HasPrefix(args[i], "-") {
				pathArg = args[i]
			}
		}
	}
	_ = allTargets
	_ = allFeatures

	// Determine target path
	var targetPath string
	if pathArg == "" {
		cwd, err := os.Getwd()
		if err != nil {
			cwd = "."
		}
		targetPath = cwd
	} else {
		targetPath = pathArg
	}

	// Check sysroot
	if !checkSysroot() {
		logInfo("rustowl::toolchain", "sysroot not found; start setup toolchain")
		installToolchain("", false)
	}

	// Check cargo
