// ============================================================
// Toolchain command
// ============================================================

func runToolchain(args []string) {
	if len(args) == 0 || args[0] == "-h" || args[0] == "--help" {
		printToolchainHelp()
		return
	}

	switch args[0] {
	case "install":
		var installPath string
		var skipRustowlToolchain bool
		for i := 1; i < len(args); i++ {
			switch args[i] {
			case "--path":
				if i+1 < len(args) {
					installPath = args[i+1]
					i++
				}
			case "--skip-rustowl-toolchain":
				skipRustowlToolchain = true
			case "-h", "--help":
				printToolchainInstallHelp()
				return
			}
		}
		installToolchain(installPath, skipRustowlToolchain)

	case "uninstall":
		for _, arg := range args[1:] {
			if arg == "-h" || arg == "--help" {
				printToolchainUninstallHelp()
				return
			}
		}
		uninstallToolchain()

	case "help":
		if len(args) > 1 {
			switch args[1] {
			case "install":
				printToolchainInstallHelp()
			case "uninstall":
				printToolchainUninstallHelp()
			default:
				printToolchainHelp()
			}
		} else {
			printToolchainHelp()
		}

	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\nFor more information, try '--help'.\n", args[0])
		os.Exit(2)
	}
}

