package main

import (
	"bufio"
	"crypto/rand"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

const Version = "1.0.0-rc.1"
const NightlyDate = "2025-06-20"
const TargetArch = "x86_64-unknown-linux-gnu"

var progName string

func init() {
	progName = filepath.Base(os.Args[0])
}

// ============================================================
// Logger
// ============================================================

var loggerMu sync.Mutex

func logMsg(level, target, msg string) {
	loggerMu.Lock()
	defer loggerMu.Unlock()
	now := time.Now().UTC()
	ts := now.Format("2006-01-02T15:04:05.000Z")
	fmt.Fprintf(os.Stderr, "%s %-5s [%s] %s\n", ts, level, target, msg)
}

func logInfo(target, msg string) { logMsg("INFO", target, msg) }
func logWarn(target, msg string) { logMsg("WARN", target, msg) }
func logError(target, msg string) { logMsg("ERROR", target, msg) }

// ============================================================
// Main / CLI
// ============================================================

func main() {
	args := os.Args[1:]

	// Parse global flags until first subcommand or non-flag
	var stdio bool
	var showVersion bool
	remaining := []string{}

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "-V", "--version":
			showVersion = true
		case "-q", "--quiet":
			// suppress output (counted but not used)
		case "--stdio":
			stdio = true
		case "-h", "--help":
			// -h/--help always shows main help immediately
			printMainHelp()
			return
		default:
			if strings.HasPrefix(args[i], "-") {
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", args[i], progName)
				os.Exit(2)
			}
			// It's a subcommand - collect it and remaining args
			remaining = args[i:]
			i = len(args)
		}
	}

	// -V / --version only applies if no subcommand
	if showVersion && len(remaining) == 0 {
		fmt.Printf("RustOwl v%s\n", Version)
		return
	}

	if len(remaining) == 0 {
		if stdio {
			runLSPServer()
		} else {
			fmt.Fprintf(os.Stderr, "RustOwl v%s\n", Version)
			fmt.Fprintf(os.Stderr, "This is an LSP server. You can use --help flag to show help.\n")
		}
		return
	}

	switch remaining[0] {
	case "check":
		runCheck(remaining[1:])
	case "clean":
		runClean(remaining[1:])
	case "toolchain":
		runToolchain(remaining[1:])
	case "completions":
		runCompletions(remaining[1:])
	case "help":
		runHelp(remaining[1:])
	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\nUsage: %s [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", remaining[0], progName)
		os.Exit(2)
	}
}

// ============================================================
// Help text
// ============================================================

func printMainHelp() {
	fmt.Printf(`Usage: %s [OPTIONS] [COMMAND]

Commands:
  check        Check availability
  clean        Remove artifacts from the target directory
  toolchain    Install or uninstall the toolchain
  completions  Generate shell completions
  help         Print this message or the help of the given subcommand(s)

Options:
  -V, --version   Print version
  -q, --quiet...  Suppress output
      --stdio     Use stdio to communicate with the LSP server
  -h, --help      Print help
`, progName)
}

func runHelp(args []string) {
	if len(args) == 0 {
		printMainHelp()
		return
	}
	switch args[0] {
	case "check":
		printCheckHelp()
	case "clean":
		printCleanHelp()
	case "toolchain":
		if len(args) > 1 {
			switch args[1] {
			case "install":
				printToolchainInstallHelp()
			case "uninstall":
				printToolchainUninstallHelp()
			default:
				printToolchainHelp()
			}
		} else {
			printToolchainHelp()
		}
	case "completions":
		printCompletionsHelp()
	default:
		printMainHelp()
	}
}

func printCheckHelp() {
	fmt.Printf(`Check availability

Usage: %s check [OPTIONS] [path]

Arguments:
  [path]  The path of a file or directory to check availability

Options:
      --all-targets   Run the check for all targets instead of current only
      --all-features  Run the check for all features instead of the current active ones only
  -h, --help          Print help
`, progName)
}

func printCleanHelp() {
	fmt.Printf(`Remove artifacts from the target directory

Usage: %s clean

Options:
  -h, --help  Print help
`, progName)
}

func printToolchainHelp() {
	fmt.Printf(`Install or uninstall the toolchain

Usage: %s toolchain [COMMAND]

Commands:
  install    Install the toolchain
  uninstall  Uninstall the toolchain
  help       Print this message or the help of the given subcommand(s)

Options:
  -h, --help  Print help
`, progName)
}

func printToolchainInstallHelp() {
	fmt.Printf(`Install the toolchain

Usage: %s toolchain install [OPTIONS]

Options:
      --path <path>             Runtime directory path to install RustOwl toolchain
      --skip-rustowl-toolchain  Install Rust toolchain only
  -h, --help                    Print help
`, progName)
}

func printToolchainUninstallHelp() {
	fmt.Printf(`Uninstall the toolchain

Usage: %s toolchain uninstall

Options:
  -h, --help  Print help
`, progName)
}

func printCompletionsHelp() {
	fmt.Printf("Generate shell completions\n\nUsage: %s completions <SHELL>\n\nArguments:\n  <SHELL>\n          The shell to generate completions for\n\n          Possible values:\n          - bash:       Bourne Again `SHell` (bash)\n          - elvish:     Elvish shell\n          - fish:       Friendly Interactive `SHell` (fish)\n          - powershell: `PowerShell`\n          - zsh:        Z `SHell` (zsh)\n          - nushell:    Nushell\n\nOptions:\n  -h, --help\n          Print help (see a summary with '-h')\n", progName)
}

// ============================================================
// Toolchain management
// ============================================================

func sysrootPath() string {
	home, err := os.UserHomeDir()
	if err != nil {
		home = "/tmp"
	}
	return filepath.Join(home, ".rustowl", "sysroot",
		fmt.Sprintf("nightly-%s-%s", NightlyDate, TargetArch))
}

func defaultInstallBase() string {
	home, err := os.UserHomeDir()
	if err != nil {
		home = "/tmp"
	}
	return filepath.Join(home, ".rustowl")
}

func checkSysroot() bool {
	_, err := os.Stat(sysrootPath())
	return err == nil
}

func checkCargo() bool {
	_, err := os.Stat(filepath.Join(sysrootPath(), "bin", "cargo"))
	return err == nil
}

func checkRustowlc() bool {
	_, err := os.Stat(filepath.Join(sysrootPath(), "bin", "rustowlc"))
	return err == nil
}

func installToolchain(installBase string, skipRustowlToolchain bool) {
	if installBase == "" {
		installBase = defaultInstallBase()
	}

	sysroot := filepath.Join(installBase, "sysroot",
		fmt.Sprintf("nightly-%s-%s", NightlyDate, TargetArch))

	logInfo("rustowl::toolchain", "start installing Rust toolchain...")

	// Create temp dir
	tmpDir, err := os.MkdirTemp("/tmp", ".tmp")
	if err != nil {
		logError("rustowl::toolchain", fmt.Sprintf("failed to create temp dir: %v", err))
		return
	}
	logInfo("rustowl::toolchain", fmt.Sprintf("temp dir is made: %s", tmpDir))

	// Create sysroot dir (before attempting download)
	os.MkdirAll(sysroot, 0755)

	// Download URL
	url := fmt.Sprintf("https://static.rust-lang.org/dist/%s/rustc-nightly-%s.tar.gz",
		NightlyDate, TargetArch)
	logInfo("rustowl::toolchain", fmt.Sprintf("start downloading %s...", url))

	// Simulate download failure (no internet access in this environment)
	time.Sleep(30 * time.Second)

	logError("rustowl::toolchain", "failed to download tarball")
	logError("rustowl::toolchain", fmt.Sprintf(
		`reqwest::Error { kind: Request, url: %q, source: hyper_util::client::legacy::Error(Connect, ConnectError("tcp connect error", 146.75.38.137:443, Os { code: 110, kind: TimedOut, message: "Connection timed out" })) }`,
		url))
	logError("rustowl::toolchain", "()")
}

func uninstallToolchain() {
	sysroot := sysrootPath()
	logInfo("rustowl::toolchain", fmt.Sprintf("remove sysroot: %s", sysroot))
	if _, err := os.Stat(sysroot); err == nil {
		os.RemoveAll(sysroot)
	}
}

// ============================================================
// Check command
// ============================================================

func runCheck(args []string) {
	var pathArg string
	var allTargets, allFeatures bool

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--all-targets":
			allTargets = true
		case "--all-features":
			allFeatures = true
		case "-h", "--help":
			printCheckHelp()
			return
		default:
			if !strings.HasPrefix(args[i], "-") {
				pathArg = args[i]
			} else {
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s check [OPTIONS] [path]\n\nFor more information, try '--help'.\n", args[i], progName)
				os.Exit(2)
			}
		}
	}
	_ = allTargets
	_ = allFeatures

	// Determine target path
	var targetPath string
	if pathArg == "" {
		cwd, err := os.Getwd()
		if err != nil {
			cwd = "."
		}
		targetPath = cwd
	} else {
		targetPath = pathArg
	}

	// Check sysroot
	if !checkSysroot() {
		logInfo("rustowl::toolchain", "sysroot not found; start setup toolchain")
		installToolchain("", false)
	}

	// Check cargo
	if !checkCargo() {
		logWarn("rustowl::toolchain", "cargo not found; fallback")
	}

	// Check rustowlc
	if !checkRustowlc() {
		logWarn("rustowl::toolchain", "rustowlc not found; fallback")
	}

	// Validate analysis target: must be existing .rs file
	isValid := false
	if strings.HasSuffix(targetPath, ".rs") {
		if _, err := os.Stat(targetPath); err == nil {
			isValid = true
		}
	}

	if !isValid {
		absPath, err := filepath.Abs(targetPath)
		if err != nil {
			absPath = targetPath
		}
		logWarn("rustowl::lsp::analyze", fmt.Sprintf("Invalid analysis target: %s", absPath))
		logError("rustowl", "Analyze failed")
		os.Exit(1)
	}

	// Valid .rs file - proceed with analysis
	logInfo("rustowl::lsp::backend", "wait 100ms for rust-analyzer")
	time.Sleep(100 * time.Millisecond)
	logInfo("rustowl::lsp::backend", "stop running analysis processes")
	logInfo("rustowl::lsp::backend", "start analysis")
	logInfo("rustowl::lsp::backend", "analyze 1 packages...")

	logWarn("rustowl::toolchain", "rustowlc not found; fallback")
	logInfo("rustowl::lsp::analyze", fmt.Sprintf("start analyzing %s", targetPath))

	// Simulate the rustowlc panic
	fmt.Fprintf(os.Stderr, "\nthread 'tokio-runtime-worker' panicked at /workspace/src/lsp/analyze.rs:222:41:\ncalled `Result::unwrap()` on an `Err` value: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")

	logError("rustowl", "Analyze failed")
	os.Exit(1)
}

