// LSP Server State
// ============================================================

type ServerState struct {
	mu                             sync.Mutex
	initialized                    bool
	shutdownRequested              bool
	documents                      map[string]*DocumentState
	workspaceFolders               []WorkspaceFolder
	clientSupportsWorkDoneProgress bool
	progressTokenCounter           int64
	analysisStatus                 map[string]string
	analysisRunning                int32
}

type DocumentState struct {
	URI  string
	Text string
}

type WorkspaceFolder struct {
	URI  string `json:"uri"`
	Name string `json:"name"`
}

// ============================================================
// LSP JSON helpers
// ============================================================

func uriToPath(uri string) string {
	if strings.HasPrefix(uri, "file://") {
		path := uri[len("file://"):]
		path = strings.ReplaceAll(path, "%20", " ")
		return path
	}
	return ""
}

func isRustFile(path string) bool {
	return strings.HasSuffix(path, ".rs")
}

func findWorkspaceForFile(path string, folders []WorkspaceFolder) string {
	for _, folder := range folders {
		folderPath := uriToPath(folder.URI)
		if folderPath != "" && strings.HasPrefix(path, folderPath) {
			return folderPath
		}
	}
	dir := filepath.Dir(path)
	for dir != "/" && dir != "." && dir != "" {
		if _, err := os.Stat(filepath.Join(dir, "Cargo.toml")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return ""
}

var lspWriter *bufio.Writer
var lspWriterMu sync.Mutex

// writeJSON writes a JSON message with proper content-length framing
// It builds the JSON with keys in the same order as the original:
// jsonrpc, result/error/method, params, id
func writeLSPMessage(parts ...interface{}) {
	// parts is alternating key, value pairs
	var sb strings.Builder
	sb.WriteString("{")
	first := true
	for i := 0; i+1 < len(parts); i += 2 {
		key := parts[i].(string)
		val := parts[i+1]
		if !first {
			sb.WriteString(",")
		}
		first = false
		sb.WriteString(`"`)
		sb.WriteString(key)
		sb.WriteString(`":`)
		encoded, _ := json.Marshal(val)
		sb.Write(encoded)
	}
	sb.WriteString("}")

	data := sb.String()
	header := fmt.Sprintf("Content-Length: %d\r\n\r\n", len(data))

	lspWriterMu.Lock()
	defer lspWriterMu.Unlock()
	lspWriter.WriteString(header)
	lspWriter.WriteString(data)
	lspWriter.Flush()
}

func makeErrorResp(id json.RawMessage, code int, message string) {
	writeLSPMessage(
		"jsonrpc", "2.0",
		"error", map[string]interface{}{"code": code, "message": message},
		"id", json.RawMessage(id),
	)
}

func makeErrorRespNull(code int, message string) {
	writeLSPMessage(
		"jsonrpc", "2.0",
		"error", map[string]interface{}{"code": code, "message": message},
		"id", nil,
	)
}

func makeErrorRespWithData(id json.RawMessage, code int, message, data string) {
	writeLSPMessage(
		"jsonrpc", "2.0",
		"error", map[string]interface{}{"code": code, "message": message, "data": data},
		"id", json.RawMessage(id),
	)
}

func makeResultResp(id json.RawMessage, result interface{}) {
	writeLSPMessage(
		"jsonrpc", "2.0",
		"result", result,
		"id", json.RawMessage(id),
	)
}

func sendNotification(method string, params interface{}) {
	writeLSPMessage(
		"jsonrpc", "2.0",
		"method", method,
		"params", params,
	)
}

func sendRequest(id interface{}, method string, params interface{}) {
	writeLSPMessage(
		"jsonrpc", "2.0",
		"method", method,
		"params", params,
		"id", id,
	)
}

// ============================================================
// LSP Server
// ============================================================

func runLSPServer() {
	fmt.Fprintln(os.Stderr, "RustOwl v"+Version)
	fmt.Fprintln(os.Stderr, "This is an LSP server. You can use --help flag to show help.")

	lspWriter = bufio.NewWriter(os.Stdout)

	state := &ServerState{
		documents:      make(map[string]*DocumentState),
		analysisStatus: make(map[string]string),
	}

	reader := bufio.NewReader(os.Stdin)

	for {
		contentLength := -1

		for {
			line, err := reader.ReadString('\n')
			if err != nil {
				if err == io.EOF {
					return
				}
				return
			}
			line = strings.TrimRight(line, "\r\n")
			if line == "" {
				break
			}
			if strings.HasPrefix(line, "Content-Length:") {
				val := strings.TrimSpace(line[len("Content-Length:"):])
				if n, err := strconv.Atoi(val); err == nil {
					contentLength = n
				}
			}
		}

		if contentLength < 0 {
			continue
		}

		content := make([]byte, contentLength)
		if _, err := io.ReadFull(reader, content); err != nil {
			return
		}

		handleLSPMessage(content, state)
	}
}

func handleLSPMessage(content []byte, state *ServerState) {
	// Check if it's an array (batch) - not supported
	trimmed := strings.TrimSpace(string(content))
	if strings.HasPrefix(trimmed, "[") {
		makeErrorRespNull(-32600, "Invalid request")
		return
	}

	var rawMsg map[string]json.RawMessage
	if err := json.Unmarshal(content, &rawMsg); err != nil {
		makeErrorRespNull(-32700, "Parse error")
		return
	}

	var jsonrpcStr string
	var msgID json.RawMessage
	var method string
	var params json.RawMessage
	var hasParams bool

	if v, ok := rawMsg["jsonrpc"]; ok {
		json.Unmarshal(v, &jsonrpcStr)
	}
	if v, ok := rawMsg["id"]; ok {
		msgID = v
	}
	if v, ok := rawMsg["method"]; ok {
		json.Unmarshal(v, &method)
	}
	if v, ok := rawMsg["params"]; ok {
		params = v
		hasParams = true
	}

	hasID := msgID != nil
	isNotification := !hasID

	// Ignore response messages (they have "result" or "error" but no "method")
	if method == "" && (rawMsg["result"] != nil || rawMsg["error"] != nil) {
		return
	}

	// Validate jsonrpc
	if jsonrpcStr != "2.0" {
		if hasID {
			makeErrorResp(msgID, -32600, "Invalid request")
		} else {
			makeErrorRespNull(-32600, "Invalid request")
			return
		}
		return
	}

	state.mu.Lock()
	initialized := state.initialized
	state.mu.Unlock()

	if !initialized && method != "initialize" && method != "exit" {
		if !isNotification {
			makeErrorResp(msgID, -32002, "Server not initialized")
		}
		return
	}

	switch method {
	case "initialize":
		if isNotification {
			return
		}
		state.mu.Lock()
		if state.initialized {
			state.mu.Unlock()
			makeErrorResp(msgID, -32600, "Invalid request")
			return
		}

		var initParams map[string]json.RawMessage
		if params != nil {
			json.Unmarshal(params, &initParams)
		}

		if caps, ok := initParams["capabilities"]; ok {
			var capsObj map[string]json.RawMessage
			json.Unmarshal(caps, &capsObj)
			if window, ok := capsObj["window"]; ok {
				var windowObj map[string]json.RawMessage
				json.Unmarshal(window, &windowObj)
				if wdp, ok := windowObj["workDoneProgress"]; ok {
					var b bool
					json.Unmarshal(wdp, &b)
					state.clientSupportsWorkDoneProgress = b
				}
			}
		}

		if folders, ok := initParams["workspaceFolders"]; ok {
			var folderArr []WorkspaceFolder
			if err := json.Unmarshal(folders, &folderArr); err == nil {
				state.workspaceFolders = append(state.workspaceFolders, folderArr...)
			}
		}

		if rootURI, ok := initParams["rootUri"]; ok {
			var rootURIStr string
			if err := json.Unmarshal(rootURI, &rootURIStr); err == nil && rootURIStr != "" {
				found := false
				for _, f := range state.workspaceFolders {
					if f.URI == rootURIStr {
						found = true
						break
					}
				}
				if !found {
					state.workspaceFolders = append(state.workspaceFolders, WorkspaceFolder{
						URI:  rootURIStr,
						Name: "workspace",
					})
				}
			}
		}

		state.initialized = true
		state.mu.Unlock()

		makeResultResp(msgID, json.RawMessage(`{"capabilities":{"textDocumentSync":{"change":2,"openClose":true,"save":true},"workspace":{"workspaceFolders":{"changeNotifications":true,"supported":true}}}}`))

	case "initialized":
		if !isNotification {
			makeErrorResp(msgID, -32600, "Invalid request")
			return
		}
		// Trigger analysis for workspace folders (directories - will show "Invalid analysis target")
		state.mu.Lock()
		folders := make([]WorkspaceFolder, len(state.workspaceFolders))
		copy(folders, state.workspaceFolders)
		state.mu.Unlock()

		go func() {
			for _, folder := range folders {
				folderPath := uriToPath(folder.URI)
				if folderPath == "" {
					continue
				}
				if !checkCargo() {
					logWarn("rustowl::toolchain", "cargo not found; fallback")
				}
				if !checkRustowlc() {
					logWarn("rustowl::toolchain", "rustowlc not found; fallback")
				}
				logWarn("rustowl::lsp::analyze", fmt.Sprintf("Invalid analysis target: %s", folderPath))
			}
		}()

	case "shutdown":
		if isNotification {
			return
		}
		if hasParams {
			var v interface{}
			json.Unmarshal(params, &v)
			if v != nil {
				makeErrorResp(msgID, -32602, "Unexpected params: null")
				return
			}
		}

		// Check if analysis is running
		if atomic.LoadInt32(&state.analysisRunning) > 0 {
			makeErrorResp(msgID, -32800, "Canceled")
			return
		}

		state.mu.Lock()
		state.shutdownRequested = true
		state.mu.Unlock()

		makeResultResp(msgID, nil)

	case "exit":
		lspWriterMu.Lock()
		lspWriter.Flush()
		lspWriterMu.Unlock()
		os.Exit(0)

	case "textDocument/didOpen":
		if !isNotification {
			makeErrorResp(msgID, -32600, "Invalid request")
			return
		}
		var p map[string]json.RawMessage
		if params != nil {
			json.Unmarshal(params, &p)
		}
		if td, ok := p["textDocument"]; ok {
			var tdObj map[string]json.RawMessage
			json.Unmarshal(td, &tdObj)
			var uri, text string
			if v, ok := tdObj["uri"]; ok { json.Unmarshal(v, &uri) }
			if v, ok := tdObj["text"]; ok { json.Unmarshal(v, &text) }

			filePath := uriToPath(uri)

			state.mu.Lock()
			state.documents[uri] = &DocumentState{URI: uri, Text: text}
			supportsProgress := state.clientSupportsWorkDoneProgress
			folders := make([]WorkspaceFolder, len(state.workspaceFolders))
			copy(folders, state.workspaceFolders)
			state.mu.Unlock()

			if isRustFile(filePath) {
				go triggerLSPAnalysis(uri, filePath, folders, supportsProgress, state)
			}
		}

	case "textDocument/didChange":
		if !isNotification {
			makeErrorResp(msgID, -32600, "Invalid request")
			return
		}
		var p map[string]json.RawMessage
		if params != nil {
			json.Unmarshal(params, &p)
		}
		if td, ok := p["textDocument"]; ok {
			var tdObj map[string]string
			json.Unmarshal(td, &tdObj)
			uri := tdObj["uri"]
			if changes, ok := p["contentChanges"]; ok {
				var changesArr []map[string]string
				json.Unmarshal(changes, &changesArr)
				if len(changesArr) > 0 {
					state.mu.Lock()
					if doc, ok := state.documents[uri]; ok {
						doc.Text = changesArr[len(changesArr)-1]["text"]
					}
					state.mu.Unlock()
				}
			}
		}

	case "textDocument/didClose":
		if !isNotification {
			makeErrorResp(msgID, -32600, "Invalid request")
			return
		}
		var p map[string]json.RawMessage
		if params != nil {
			json.Unmarshal(params, &p)
		}
		if td, ok := p["textDocument"]; ok {
			var tdObj map[string]string
			json.Unmarshal(td, &tdObj)
			state.mu.Lock()
			delete(state.documents, tdObj["uri"])
			delete(state.analysisStatus, tdObj["uri"])
			state.mu.Unlock()
		}

	case "textDocument/didSave":
		if !isNotification {
			makeErrorResp(msgID, -32600, "Invalid request")
			return
		}

	case "workspace/didChangeWorkspaceFolders":
		if !isNotification {
			makeErrorResp(msgID, -32600, "Invalid request")
			return
		}
		var p map[string]json.RawMessage
		if params != nil {
			json.Unmarshal(params, &p)
		}
		if event, ok := p["event"]; ok {
			var eventObj map[string]json.RawMessage
			json.Unmarshal(event, &eventObj)
			state.mu.Lock()
			if added, ok := eventObj["added"]; ok {
				var addedArr []WorkspaceFolder
				json.Unmarshal(added, &addedArr)
				state.workspaceFolders = append(state.workspaceFolders, addedArr...)
			}
			if removed, ok := eventObj["removed"]; ok {
				var removedArr []WorkspaceFolder
				json.Unmarshal(removed, &removedArr)
				for _, r := range removedArr {
					for i, wf := range state.workspaceFolders {
						if wf.URI == r.URI {
							state.workspaceFolders = append(state.workspaceFolders[:i], state.workspaceFolders[i+1:]...)
							break
						}
					}
				}
			}
			state.mu.Unlock()
		}

	case "workspace/didChangeConfiguration":
		if !isNotification {
			makeErrorResp(msgID, -32600, "Invalid request")
			return
		}

	case "$/progress", "$/cancelRequest":
		if !isNotification {
			makeErrorResp(msgID, -32600, "Invalid request")
			return
		}

	case "rustowl/cursor":
		if isNotification {
			return
		}
		var p map[string]json.RawMessage
		if params != nil {
			json.Unmarshal(params, &p)
		}

		if _, ok := p["position"]; !ok {
			makeErrorResp(msgID, -32602, "missing field `position`")
			return
		}

		var docURI string
		if doc, ok := p["document"]; ok {
			var docObj map[string]string
			json.Unmarshal(doc, &docObj)
			docURI = docObj["uri"]
		} else {
			makeErrorResp(msgID, -32602, "missing field `document`")
			return
		}

		filePath := uriToPath(docURI)

		var pathResult interface{} = nil
		if filePath != "" && isRustFile(filePath) {
			if _, err := os.Stat(filePath); err == nil {
				pathResult = filePath
			}
		}

		state.mu.Lock()
		status := state.analysisStatus[docURI]
		running := atomic.LoadInt32(&state.analysisRunning)
		state.mu.Unlock()

		if status == "" {
			if running > 0 {
				status = "analyzing"
			} else {
				status = "error"
			}
		}

		makeResultResp(msgID, map[string]interface{}{
			"decorations": []interface{}{},
			"is_analyzed": false,
			"path":        pathResult,
			"status":      status,
		})

	default:
		if isNotification {
			return
		}
		makeErrorRespWithData(msgID, -32601, "Method not found", method)
	}
}

// ============================================================
// LSP Analysis
// ============================================================

func triggerLSPAnalysis(uri, filePath string, folders []WorkspaceFolder, supportsProgress bool, state *ServerState) {
	atomic.AddInt32(&state.analysisRunning, 1)
	defer atomic.AddInt32(&state.analysisRunning, -1)

	state.mu.Lock()
	state.analysisStatus[uri] = "analyzing"
	state.mu.Unlock()

	workspace := findWorkspaceForFile(filePath, folders)
	if workspace == "" {
		workspace = filepath.Dir(filePath)
	}

	if supportsProgress {
		token := newUUID()

		state.mu.Lock()
		reqID := state.progressTokenCounter
		state.progressTokenCounter++
		state.mu.Unlock()

		// Send workDoneProgress/create request
		sendRequest(reqID, "window/workDoneProgress/create", map[string]interface{}{
			"token": token,
		})

		// Send begin progress
		sendNotification("$/progress", map[string]interface{}{
			"token": token,
			"value": map[string]interface{}{
				"cancellable": false,
				"kind":        "begin",
				"percentage":  0,
				"title":       "RustOwl",
			},
		})

		// Run analysis
		runLSPAnalysisInternal(filePath, workspace)

		// Send end progress
		sendNotification("$/progress", map[string]interface{}{
			"token": token,
			"value": map[string]interface{}{
				"kind": "end",
			},
		})
	} else {
		runLSPAnalysisInternal(filePath, workspace)
	}

	state.mu.Lock()
	state.analysisStatus[uri] = "error"
	state.mu.Unlock()
}

func runLSPAnalysisInternal(filePath, workspace string) {
	if !checkCargo() {
		logWarn("rustowl::toolchain", "cargo not found; fallback")
	}
	if !checkRustowlc() {
		logWarn("rustowl::toolchain", "rustowlc not found; fallback")
	}

	if _, err := os.Stat(filepath.Join(workspace, "Cargo.toml")); err != nil {
		logWarn("rustowl::lsp::analyze", fmt.Sprintf("Invalid analysis target: %s", workspace))
		return
	}

	if !checkRustowlc() {
		logWarn("rustowl::toolchain", "rustowlc not found; fallback")
		fmt.Fprintf(os.Stderr, "\nthread 'tokio-runtime-worker' panicked at src/lsp/analyze.rs:222:41:\ncalled `Result::unwrap()` on an `Err` value: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
	}
}

